function verify(req, res, next) {
  const ts = req.header('x-timestamp');
  const sig = req.header('x-signature');
  if (Math.abs(Date.now()/1000 - Number(ts)) > 300) return res.status(401).send('expired');
  const payload = `${ts}.${req.method}.${req.path}.${JSON.stringify(req.body)}`;
  const expected = crypto.createHmac('sha256', '{{secret}}').update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig))) return res.status(401).send('bad sig');
  next();
}
